-- Proposed PostgreSQL foundation. Do not apply to an existing database without backup and review.
-- IDs are generated by the application; all cross-table tenant references are explicit.
BEGIN;

CREATE TABLE crm_tenant (
    id UUID PRIMARY KEY,
    name TEXT NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 200),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE crm_staff (
    tenant_id UUID NOT NULL REFERENCES crm_tenant(id),
    id UUID NOT NULL,
    login_name TEXT NOT NULL CHECK (length(btrim(login_name)) BETWEEN 1 AND 150),
    password_hash TEXT NOT NULL,
    role TEXT NOT NULL CHECK (role IN ('sales', 'manager')),
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    auth_version BIGINT NOT NULL DEFAULT 1 CHECK (auth_version > 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, id),
    UNIQUE (tenant_id, login_name)
);

CREATE TABLE crm_session (
    token_hash CHAR(64) PRIMARY KEY,
    tenant_id UUID NOT NULL,
    staff_id UUID NOT NULL,
    auth_version BIGINT NOT NULL CHECK (auth_version > 0),
    expires_at TIMESTAMPTZ NOT NULL,
    revoked_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    FOREIGN KEY (tenant_id, staff_id) REFERENCES crm_staff(tenant_id, id)
);
CREATE INDEX crm_session_staff_idx ON crm_session(tenant_id, staff_id);

CREATE TABLE crm_customer (
    tenant_id UUID NOT NULL REFERENCES crm_tenant(id),
    id UUID NOT NULL,
    legacy_client_id TEXT,
    owner_staff_id UUID,
    company TEXT NOT NULL DEFAULT '',
    contact_name TEXT NOT NULL DEFAULT '',
    address TEXT NOT NULL DEFAULT '',
    requirement TEXT NOT NULL DEFAULT '',
    tier TEXT NOT NULL DEFAULT '' CHECK (tier IN ('', 'A', 'B', 'C')),
    channel TEXT NOT NULL CHECK (channel IN ('email', 'alibaba')),
    status TEXT NOT NULL DEFAULT 'new',
    row_version BIGINT NOT NULL DEFAULT 1 CHECK (row_version > 0),
    deleted_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, id),
    UNIQUE (tenant_id, legacy_client_id),
    FOREIGN KEY (tenant_id, owner_staff_id) REFERENCES crm_staff(tenant_id, id)
);
CREATE INDEX crm_customer_owner_idx ON crm_customer(tenant_id, owner_staff_id, tier) WHERE deleted_at IS NULL;

CREATE TABLE crm_product (
    tenant_id UUID NOT NULL REFERENCES crm_tenant(id),
    id UUID NOT NULL,
    internal_code TEXT NOT NULL CHECK (length(btrim(internal_code)) > 0),
    name TEXT NOT NULL,
    PRIMARY KEY (tenant_id, id),
    UNIQUE (tenant_id, internal_code)
);

CREATE TABLE crm_pricing_policy_version (
    tenant_id UUID NOT NULL REFERENCES crm_tenant(id),
    version BIGINT NOT NULL CHECK (version > 0),
    minimum_year INTEGER NOT NULL CHECK (minimum_year BETWEEN 1900 AND 9999),
    review_after_days INTEGER NOT NULL CHECK (review_after_days > 0),
    allow_history BOOLEAN NOT NULL DEFAULT FALSE,
    created_by UUID NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, version),
    FOREIGN KEY (tenant_id, created_by) REFERENCES crm_staff(tenant_id, id)
);

CREATE TABLE crm_price_version (
    tenant_id UUID NOT NULL,
    id UUID NOT NULL,
    product_id UUID NOT NULL,
    customer_id UUID,
    specification TEXT NOT NULL CHECK (length(btrim(specification)) > 0),
    currency TEXT NOT NULL CHECK (length(btrim(currency)) > 0),
    unit TEXT NOT NULL CHECK (length(btrim(unit)) > 0),
    trade_term TEXT NOT NULL CHECK (length(btrim(trade_term)) > 0),
    amount NUMERIC(20,6) NOT NULL CHECK (amount > 0),
    min_quantity NUMERIC(20,6) NOT NULL CHECK (min_quantity > 0),
    max_quantity_exclusive NUMERIC(20,6),
    revision BIGINT NOT NULL CHECK (revision > 0),
    status TEXT NOT NULL CHECK (status IN ('draft', 'approved', 'revoked')),
    published_at TIMESTAMPTZ,
    valid_from TIMESTAMPTZ NOT NULL,
    valid_until_exclusive TIMESTAMPTZ,
    source_ref TEXT NOT NULL CHECK (length(btrim(source_ref)) > 0),
    supersedes_id UUID,
    created_by UUID NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, id),
    FOREIGN KEY (tenant_id, product_id) REFERENCES crm_product(tenant_id, id),
    FOREIGN KEY (tenant_id, customer_id) REFERENCES crm_customer(tenant_id, id),
    FOREIGN KEY (tenant_id, supersedes_id) REFERENCES crm_price_version(tenant_id, id),
    FOREIGN KEY (tenant_id, created_by) REFERENCES crm_staff(tenant_id, id),
    CHECK (max_quantity_exclusive IS NULL OR max_quantity_exclusive > min_quantity),
    CHECK (valid_until_exclusive IS NULL OR valid_until_exclusive > valid_from),
    CHECK (status = 'draft' OR published_at IS NOT NULL),
    CHECK (supersedes_id IS NULL OR supersedes_id <> id)
);
CREATE INDEX crm_price_lookup_idx ON crm_price_version(tenant_id, product_id, status, valid_from DESC);

CREATE TABLE crm_audit_event (
    tenant_id UUID NOT NULL,
    id UUID NOT NULL,
    actor_id UUID NOT NULL,
    action TEXT NOT NULL,
    target_type TEXT NOT NULL,
    target_id UUID NOT NULL,
    trace_id TEXT NOT NULL,
    occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, id),
    FOREIGN KEY (tenant_id, actor_id) REFERENCES crm_staff(tenant_id, id)
);

COMMIT;